<form class="homepage-form homepage-inline-form" method="post" action="{{ route('staff.homepage.slides') }}" enctype="multipart/form-data">@csrf @if(isset($slide))<input type="hidden" name="id" value="{{ $slide->id }}">@endif<label>Media type<select name="media_type"><option value="image" @selected(($slide->media_type ?? 'image') === 'image')>Image</option><option value="video" @selected(($slide->media_type ?? '') === 'video')>Hosted video</option><option value="external_video" @selected(($slide->media_type ?? '') === 'external_video')>YouTube or Vimeo URL</option></select></label><label>{{ isset($slide) ? 'Replace media' : 'Upload image or video' }}<input name="media_upload" type="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,video/ogg"></label><label>Media URL<input name="media_url" type="url" value="{{ $slide->media_url ?? '' }}" placeholder="https://…"></label><label>Eyebrow<input name="eyebrow" maxlength="80" value="{{ $slide->eyebrow ?? '' }}" placeholder="Welcome"></label><label>Title<input name="title" required maxlength="180" value="{{ $slide->title ?? '' }}" placeholder="A message worth sharing"></label><label>Supporting text<textarea name="body" rows="3">{{ $slide->body ?? '' }}</textarea></label><label>Button text<input name="button_label" maxlength="60" value="{{ $slide->button_label ?? '' }}" placeholder="Plan your visit"></label><label>Button link<input name="button_url" type="url" value="{{ $slide->button_url ?? '' }}" placeholder="https://…"></label><label>Image/video description<input name="alt_text" maxlength="180" value="{{ $slide->alt_text ?? '' }}"></label><label class="check-field"><input type="checkbox" name="is_published" value="1" @checked($slide->is_published ?? false)> Publish this slide</label><button class="button" type="submit">{{ isset($slide) ? 'Save slide' : 'Add slide' }}</button></form>
